SELECT substr(date, 1, 10) AS date, COUNT(*) AS count FROM transactions
         WHERE date >= ? AND date < ? AND status = ?
         GROUP BY substr(date, 1, 10);

SELECT COALESCE(civil_date, substr(date, 1, 10)) AS date, COUNT(*) AS count FROM transactions
         WHERE COALESCE(civil_date, substr(date, 1, 10)) >= ? AND COALESCE(civil_date, substr(date, 1, 10)) < ? AND status = ?
         GROUP BY COALESCE(civil_date, substr(date, 1, 10));

